export function renderAcademicView(win,{esc,semesters,subjects,suppliedCgpa,academicMetrics,gpaSeries,semesterSubjects,standoutSubjects,renderGpaChart}) {
 const s=win.appState??{},section=s.section??'overview',termId=semesters.some(t=>t.id===s.semesterId)?s.semesterId:semesters[0].id;
 const metrics=academicMetrics(),selected=subjects.find(x=>x.id===s.subjectDetail),current=semesterSubjects(termId);
 const tabs=[['overview','Overview'],['semesters','Semesters'],['standout','Standout Scores'],['subjects','Subject Details'],['insights','Insights']];
 const opts=semesters.map(t=>`<option value="${t.id}" ${t.id===termId?'selected':''}>${esc(t.label)}</option>`).join('');
 const table=rows=>`<div class="table-scroll"><table><thead><tr><th>Subject</th><th>Code</th><th>Marks</th><th>Grade</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="text-button" data-subject="${x.id}">${esc(x.name)}</button></td><td>${esc(x.code)}</td><td>${x.marks} / 100</td><td>${esc(x.grade)}</td></tr>`).join('')||'<tr><td colspan="4">No subjects match these filters.</td></tr>'}</tbody></table></div>`;
 let content='';
 if(section==='overview') content=`<div class="metric-grid"><article><small>CGPA</small><strong>${suppliedCgpa.toFixed(2)} / 10</strong><span>Cumulative GPA</span></article><article><small>Best Semester GPA</small><strong>${metrics.bestSemester.gpa.toFixed(2)} / 10</strong><span>${esc(metrics.bestSemester.label)}</span></article><article><small>Semesters recorded</small><strong>${metrics.semesterCount}</strong><span>Academic history</span></article><article><small>Best programming-related score</small><strong>${metrics.bestTechnical.marks} / 100</strong><span>${esc(metrics.bestTechnical.name)} · Semester ${metrics.bestTechnical.semesterId.slice(-1)}</span><button class="text-button" data-subject="${metrics.bestTechnical.id}">View subject →</button></article></div>${renderGpaChart(gpaSeries())}<section class="panel"><h2>Academic highlights</h2><div class="highlight-grid"><p>Highest GPA <strong>9.04 · Semester 3</strong></p><p>Current recorded GPA <strong>9.00 · Semester 4</strong></p><p>CGPA <strong>8.82 / 10</strong></p><p>Top technical score <strong>98 / 100</strong></p></div><button class="text-button" data-academic-section="standout">Explore Standout Scores →</button> <button class="text-button" data-academic-section="semesters">View semester records →</button></section>`;
 else if(section==='semesters') {const sort=s.subjectSort??'name',q=(s.subjectQuery??'').toLowerCase(),rows=current.filter(x=>!q||`${x.name} ${x.code}`.toLowerCase().includes(q)).sort((a,b)=>sort==='score'?b.marks-a.marks:sort==='code'?a.code.localeCompare(b.code):a.name.localeCompare(b.name));content=`<section class="panel"><div class="page-heading"><div><h2>Semester explorer</h2><p class="muted">${current.length} subjects · GPA ${semesters.find(t=>t.id===termId).gpa.toFixed(2)} / 10</p></div><div class="filters"><select data-semester aria-label="Select semester">${opts}</select><input data-semester-search placeholder="Search subjects" aria-label="Search semester subjects" value="${esc(s.subjectQuery??'')}"><select data-subject-sort aria-label="Sort subjects"><option value="name">Name A–Z</option><option value="code" ${sort==='code'?'selected':''}>Course code</option><option value="score" ${sort==='score'?'selected':''}>Marks</option></select></div></div>${table(rows)}</section>`;}
 else if(section==='standout') {const rows=standoutSubjects(subjects,{query:s.standoutQuery??'',semester:s.standoutSemester??'all',sort:s.standoutSort??'score'});content=`<section class="panel"><div class="page-heading"><div><h2>Standout Scores</h2><p class="muted">Selected technical performances across four semesters.</p></div><div class="filters"><input data-standout-search placeholder="Search subject or code" aria-label="Search standout subjects" value="${esc(s.standoutQuery??'')}"><select data-standout-semester aria-label="Filter by semester"><option value="all">All semesters</option>${opts}</select><select data-standout-sort aria-label="Sort standout scores"><option value="score">Score · highest first</option><option value="semester" ${s.standoutSort==='semester'?'selected':''}>Semester</option></select><button data-clear-standout>Clear</button></div></div><div class="standout-grid">${rows.map(x=>`<button class="standout-card band-${x.marks>=95?'exceptional':x.marks>=90?'strong':'solid'}" data-subject="${x.id}"><span class="score">${x.marks}<small>/100</small></span><strong>${esc(x.name)}</strong><span>${esc(x.code)} · ${esc(semesters.find(t=>t.id===x.semesterId).label)}</span><i style="--score:${x.marks}%"></i><small>${x.marks}% · ${x.marks>=95?'Exceptional':x.marks>=90?'Strong':'Solid'} visual band</small></button>`).join('')||'<p class="empty">No standout scores match these filters.</p>'}</div></section>`;}
 else if(section==='subjects') {if(selected)content=`<section class="panel subject-detail"><button class="text-button" data-subject-back>← All subjects</button><p class="kicker">SUBJECT DETAILS</p><h2>${esc(selected.name)}</h2><dl><dt>Course code</dt><dd>${esc(selected.code)}</dd><dt>Semester</dt><dd>${esc(semesters.find(t=>t.id===selected.semesterId).label)}</dd><dt>Marks</dt><dd>${selected.marks} / 100</dd><dt>Grade</dt><dd>${esc(selected.grade)}</dd></dl>${selected.tags.length?`<h3>Related concepts</h3><div class="chips">${selected.tags.map(tag=>`<span>${esc(tag)}</span>`).join('')}</div>`:''}</section>`;else{const q=(s.subjectQuery??'').toLowerCase();content=`<section class="panel"><div class="page-heading"><div><h2>Subject Details</h2><p class="muted">Browse all ${subjects.length} course records.</p></div><input data-all-subject-search placeholder="Search name or code" aria-label="Search all subjects" value="${esc(s.subjectQuery??'')}"></div><div class="table-scroll"><table><thead><tr><th>Subject</th><th>Code</th><th>Semester</th><th>Marks</th><th>Grade</th></tr></thead><tbody>${subjects.filter(x=>!q||`${x.name} ${x.code}`.toLowerCase().includes(q)).map(x=>`<tr><td><button class="text-button" data-subject="${x.id}">${esc(x.name)}</button></td><td>${esc(x.code)}</td><td>${esc(semesters.find(t=>t.id===x.semesterId).label)}</td><td>${x.marks} / 100</td><td>${esc(x.grade)}</td></tr>`).join('')||'<tr><td colspan="5">No subjects match this search.</td></tr>'}</tbody></table></div></section>`;}}
 else if(section==='insights')content=`<div class="metric-grid"><article><small>Highest semester GPA</small><strong>${metrics.bestSemester.gpa.toFixed(2)}</strong><span>${esc(metrics.bestSemester.label)}</span></article><article><small>Top technical score</small><strong>${metrics.bestTechnical.marks} / 100</strong><span>${esc(metrics.bestTechnical.name)}</span></article><article><small>Technical subjects ≥ 90</small><strong>${metrics.technical90Count}</strong><span>Technical subjects</span></article><article><small>Highest overall subject mark</small><strong>${metrics.highestOverall.marks} / 100</strong><span>${esc(metrics.highestOverall.name)} · overall high score</span></article></div><section class="panel"><h2>GPA progression</h2>${renderGpaChart(gpaSeries())}</section>`;
 return `<div class="academic-page"><div class="academic-heading"><div><p class="kicker">ACADEMIC PERFORMANCE</p><h1>Academic Center</h1></div></div><nav class="academic-tabs" aria-label="Academic views">${tabs.map(([key,label])=>`<button data-academic-section="${key}" class="${section===key?'active':''}" ${section===key?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="academic-content">${content}</div></div>`;
}
